-- PT118-S4-Q13. Batch 05.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT118-S4-Q13$batch05$ AND q.stimulus=$batch05$Art theft from museums is on the rise. Most stolen art is sold to wealthy private collectors. Consequently, since thieves steal what their customers are most interested in buying, museums ought to focus more of their security on their most valuable pieces.$batch05$ AND q.prompt=$batch05$The argument depends on assuming which one of the following?$batch05$ AND q.correct_choice=$batch05$B$batch05$) THEN RAISE EXCEPTION 'Question changed: PT118-S4-Q13'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT118-S4-Q13$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT118-S4-Q13'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT118-S4-Q13$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$Museums should focus more of their security on their most valuable pieces.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$Most stolen art goes to wealthy private collectors, and thieves steal what their customers most want to buy.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$Follow the chain: thieves steal what collectors want, so protect the valuable pieces. The missing step is that collectors want the *valuable* pieces. If wealthy collectors were just as eager for modest works, the thieves would go after those too, and the advice would point nowhere.$batch05$), (3, $batch05$Goal$batch05$, $batch05$A link: what collectors want is the valuable art.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT118-S4-Q13$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$Thieves taking some of both kinds does not affect where the extra security should go.$batch05$), ($batch05$B$batch05$, $batch05$Stated from the other side: the less valuable pieces are not in demand. Negate it: "less valuable pieces *are* very much in demand by wealthy collectors." Then thieves target them too, and there is no reason to shift security toward the most valuable pieces.$batch05$), ($batch05$C$batch05$, $batch05$How well a museum is secured overall is a different issue from which pieces inside it to guard.$batch05$), ($batch05$D$batch05$, $batch05$This is the top trap, and it sounds like a premise for "focus *more*." But the recommendation works from any starting point. Even if museums already favor their valuable art, the argument says to favor it further. Negate D and nothing breaks.$batch05$), ($batch05$E$batch05$, $batch05$What collectors do with stolen art afterward does not affect which art gets stolen.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT118-S4-Q13$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
